const { rows, getState, commandFactory, relatedItemType, polySources } = options;
const itemTypeMetadata = ArasModules.metadata.itemType;
const isPolymorphic = itemTypeMetadata.isPolymorphic(relatedItemType?.id);
const dialogSettings = {
	title: window.aras.getResource('', 'common.discard_confirmationtitle')
};
const dialogMessage = window.aras.getResource('', 'common.discard_confirmationmessage');
const selectedIds = getState().grid.selectedRows;
const getItemType = (item) => {
	if (isPolymorphic) {
		const itemTypeId = item.itemtype;
		const itemTypeName = itemTypeMetadata.getItemTypeName(itemTypeId);
		return polySources[itemTypeName];
	}

	return relatedItemType;
}
const promises = selectedIds.map(async (id) => {
	const itemId = rows.get(id, 'related_id');
	const item = rows.get(itemId);
	const itemType = getItemType(item);
	const itemTypeName = itemType.name;
	const discardCommand = commandFactory('DiscardItem', {
		item,
		itemType,
		itemTypeName,
		ignoreDialog: true
	});
	if (ArasModules.item.isDirty(itemTypeName, itemId)) {
		const topWindow = window.aras.getMostTopWindowWithAras();
		const result = await topWindow.ArasModules.Dialog.confirm(dialogMessage, dialogSettings);
		if (result === 'ok') {
			await discardCommand.execute();
		}
	} else {
		await discardCommand.execute();
	}
});
return Promise.allSettled(promises);
